#!/usr/bin/env Rscript
entry<-sub('^--file=','',grep('^--file=',commandArgs(FALSE),value=TRUE)[1]);out<-dirname(normalizePath(entry))
suppressPackageStartupMessages({library(ggplot2);library(patchwork);library(data.table);library(jsonlite);library(grid)})
d<-fread(file.path(out,'numeric/panel_d_matched_Cindex.csv'),data.table=FALSE)
d$score<-factor(d$score,levels=c('Goeminne','Oh','DISCO_Goeminne','DISCO_Oh','DISCO'))
organs<-unique(d$organ);labs<-setNames(d$display[match(organs,d$organ)],organs)
# Adapt the real d-panel function; the bar geometry, paired layout and free
# Accel scales are retained. More height/rows accommodate the two new scores.
src<-parse(file.path(Sys.getenv('DISCO_CODE_ROOT'),'sources/organ_plot_source.R'))
assignments<-Filter(function(e)is.call(e)&&identical(e[[1]],as.name('<-')),as.list(src))
pick<-function(n)assignments[[which(vapply(assignments,function(e)identical(e[[2]],as.name(n)),FALSE))]]
eval(pick('font'));font<-font+theme(axis.text=element_text(size=8,color='black'),plot.title=element_text(size=9))
raw<-paste(deparse(pick('make_one'),width.cutoff=500),collapse='\n')
adapt<-gsub('Age + sex','Original',raw,fixed=TRUE)
adapt<-sub('lim <- c(0.58, 0.82)','lim <- original_limits',adapt,fixed=TRUE)
adapt<-sub('breaks <- c(0.6, 0.7, 0.8)','breaks <- c(.55, .65, .75)',adapt,fixed=TRUE)
adapt<-sub('sub <- d[d$organ == organ & d$group == grp, ]','sub <- d[d$organ == organ & d$group == grp & d$available, ]',adapt,fixed=TRUE)
adapt<-sub('DISCO = "DISCO", Oh = "Oh ProtAge", Goeminne = "Goeminne ProtAge"','DISCO = "DISCO + Age", DISCO_Oh = "DISCO-Oh + Age", DISCO_Goeminne = "DISCO-Go + Age", Oh = "Oh ProtAge", Goeminne = "Goeminne ProtAge"',adapt,fixed=TRUE)
adapt<-sub('DISCO = "#E64B35", Oh = "grey70", Goeminne = "grey70"','DISCO = "#E64B35", DISCO_Oh = "#3C5488", DISCO_Goeminne = "#00A087", Oh = "grey70", Goeminne = "grey70"',adapt,fixed=TRUE)
adapt<-sub('scale_y_discrete(labels = yl,','scale_y_discrete(drop = FALSE, labels = yl,',adapt,fixed=TRUE)
adapt<-sub('bb <- ggplot_build(q)','if (organ == "Heart") q <- q + annotate("text", x = mean(lim), y = 4, label = "Not defined (p = 1)", size = 2.5, family = "Helvetica", color = "grey35"); bb <- ggplot_build(q)',adapt,fixed=TRUE)
stopifnot(grepl('drop = FALSE',adapt,fixed=TRUE),grepl('DISCO-Go + Age',adapt,fixed=TRUE),grepl('d$available',adapt,fixed=TRUE))
ranges<-builtdata<-list();original_limits<-c(.54,.82);eval(parse(text=adapt))
cells_code<-paste(deparse(pick('cells'),width.cutoff=500),collapse='\n')
eval(parse(text=gsub('Age + sex','Original',cells_code,fixed=TRUE)))
p<-wrap_plots(cells,ncol=3,nrow=3)+plot_annotation(caption='C-index (95% CI)',theme=theme(plot.caption=element_text(family='Helvetica',size=10,hjust=.5),plot.margin=margin(6,6,6,6)))
pdf(file.path(out,'output/pdf/Organ_clock_protein_selection_sensitivity_plot.pdf'),width=11.8,height=6.8,family='Helvetica',useDingbats=FALSE);print(p);invisible(dev.off())
writeLines(raw,file.path(out,'logs/original_make_one.R'));writeLines(adapt,file.path(out,'logs/adapted_make_one.R'))
saveRDS(list(plot=p,data=d,ranges=ranges),file.path(out,'PRIVATE/plot.rds'))
write_json(list(all_88_C_and_CI_checked=TRUE,NA_rows=2,missing='Oh Heart DISCO not defined with p=1',all_CI_visible=TRUE,original_limits=original_limits,ranges=ranges,actual_plot_source='../20261002_rebuilt_figures/02_plot.R'),file.path(out,'qa/plot_checks.json'),pretty=TRUE,auto_unbox=TRUE)
cat('PLOT COMPLETE: 88 point estimates and CIs; 2 explicit undefined cells\n')
